<?php require __DIR__.'/../bootstrap/app.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=Database::get()->prepare("INSERT INTO technician_applications(full_name,email,phone,specialization,experience_years,skills,status) VALUES(?,?,?,?,?,?,'submitted')");$s->execute([trim($_POST['name']),strtolower(trim($_POST['email'])),trim($_POST['phone']),trim($_POST['specialization']),(int)$_POST['experience'],trim($_POST['skills'])]);notice('Application submitted for review.');go('careers.php');}$title='Technician application';require __DIR__.'/../app/Views/header.php';?><section class="section"><div class="container" style="max-width:700px"><form class="formbox" method="post"><h1>Technical network application</h1><?=csrf_field()?><?php foreach(['name'=>'Full name','email'=>'Email','phone'=>'Phone','specialization'=>'Specialization','experience'=>'Years of experience','skills'=>'Skills'] as $k=>$v):?><label class="form-label"><?=e($v)?></label><input class="form-control mb-3" name="<?=e($k)?>" <?= $k==='email'?'type="email"':($k==='experience'?'type="number" min="0"':'')?> required><?php endforeach;?><button class="btn gold">Submit application</button></form></div></section><?php require __DIR__.'/../app/Views/footer.php';?>